/*==========================================================================*/

static void vin_u_parse_token (Parse_Context * const parse_context , const char token)
{
  if (!vin_c_parse_token (parse_context , token))
    {
      vin_throw_exception (parse_context , VIN_ERR_SYNTAX) ;
    }
}

